#define _CRT_SECURE_NO_WARNINGS
#include <stdio.h>

int main(void)
{
    FILE *in = fopen("data.txt", "r");
    if (in == NULL) {
        printf("Error: could not open data.txt\n");
        return 1;
    }
    int x, count = 0, sum = 0;
    while (fscanf(in, "%d", &x) == 1) {
        count++;
        sum += x;
    }
    fclose(in);
    if (count == 0) {
        printf("No data\n");
    } else {
        printf("Count: %d\n", count);
        printf("Sum: %d\n", sum);
        printf("Average: %.2f\n", (double)sum / count);
    }
    return 0;
}

