int count_above(const char filename[], int threshold)
{
    FILE *in = fopen(filename, "r");
    if (in == NULL) {
        return -1;
    }
    int x, count = 0;
    while (fscanf(in, "%d", &x) == 1) {
        if (x > threshold) count++;
    }
    fclose(in);
    return count;
}

